    struct AotStatInfo { const char *name; uint32_t pairs; const char *reason; };
    const AotStatInfo g_aotStatInfo[] = {
        {"none", 0, ""},
    };
    struct AotStatReport
    {
        ~AotStatReport()
        {
            uint64_t fastPairs = 0, slowPairs = 0;
            std::vector<std::pair<uint64_t, uint32_t>> rows;
            for (uint32_t i = 0; i < 1; ++i)
            {
                fastPairs += g_aotStat[i].fast * g_aotStatInfo[i].pairs;
                const uint64_t sp = g_aotStat[i].slow * g_aotStatInfo[i].pairs;
                slowPairs += sp;
                if (sp)
                    rows.push_back({sp, i});
            }
            if (fastPairs + slowPairs == 0)
                return;
            std::sort(rows.rbegin(), rows.rend());
            std::fprintf(stderr, "[vu:aotgen] stats: fast-path pairs %.1f%% of %llu\n", 100.0 * fastPairs / (fastPairs + slowPairs),
                         static_cast<unsigned long long>(fastPairs + slowPairs));
            for (size_t k = 0; k < rows.size() && k < 25; ++k)
                std::fprintf(stderr, "[vu:aotgen] slow %-14s %3u pairs  %5.1f%%  fast runs %llu, slow runs %llu  (%s)\n", g_aotStatInfo[rows[k].second].name,
                             g_aotStatInfo[rows[k].second].pairs, 100.0 * rows[k].first / (fastPairs + slowPairs),
                             static_cast<unsigned long long>(g_aotStat[rows[k].second].fast),
                             static_cast<unsigned long long>(g_aotStat[rows[k].second].slow), g_aotStatInfo[rows[k].second].reason);
        }
    } g_aotStatReport;
